// Day 1 question pool: Create your AWS account + compute basics. Data only; ids key saved stats, never rename or reuse.
window.QUIZ.push(
{id:"q01-001", day:1, dom:2, tags:["Regions & AZs"],
 q:"Which statement best describes an AWS Availability Zone?",
 o:["A geographic area that contains several isolated groups of data centers","One or more data centers with redundant power and networking in a Region","A site in a major city that caches content and answers DNS close to end users","A single rack of servers reserved for one customer's workloads"],
 a:[1],
 x:["That describes a Region, which is made up of multiple Availability Zones.","Correct. An AZ is one or more data centers with redundant power, networking and connectivity, isolated from other AZs but linked to them by low-latency private networking.","That describes an edge location, which services like CloudFront and Route 53 use to reach users with lower latency; you do not launch EC2 instances there.","AZs are shared, multi-tenant facilities; hardware dedicated to one customer is a tenancy option (Dedicated Hosts or Dedicated Instances), not an AZ."],
 ref:["d1w4","d1c6"], doc:"regions"},

{id:"q01-002", day:1, dom:1, tags:["Regions & AZs"],
 q:"A German healthcare provider is moving its patient portal to AWS. Regulations require that patient records are stored only within the European Union, and most users are in Germany. Which approach meets these requirements?",
 o:["Deploy in us-east-1 because it offers the widest choice of services","Deploy in any Region and serve users through CloudFront edge locations in Germany","Deploy in the Europe (Frankfurt) Region and store the records only there","Deploy across multiple Availability Zones in the Region with the lowest price"],
 a:[2],
 x:["Service breadth does not override a legal data residency requirement, and us-east-1 is in the United States.","Edge locations only cache copies of content; the records themselves would still be stored in whichever Region you chose, which might be outside the EU.","Correct. Compliance and data residency come first when choosing a Region; Frankfurt keeps the data in the EU and is close to German users for low latency.","Multiple AZs improve availability, but choosing a Region purely on price can put the data outside the EU."],
 ref:["d1w4","d1c6","d1b2"], doc:"regions"},

{id:"q01-003", day:1, dom:3, tags:["Regions & AZs"],
 q:"A startup is launching a mobile game backend that depends on a recently released AWS service. It has no data residency requirements, and nearly all players are in Southeast Asia. Which factors should most influence the choice of Region? (Choose two.)",
 o:["The Region in which the AWS account was originally created","Network latency between the Region and the players","Whether CloudFront can be enabled in that Region","Whether the required service is available in the Region","The Region closest to the company's finance department"],
 a:[1,3],
 x:["An AWS account is not tied to a Region; you can deploy into any enabled Region from the same account.","Correct. Proximity to users lowers latency, which matters a lot for an interactive game.","CloudFront is a global service that uses edge locations worldwide; its use does not depend on which Region hosts the backend.","Correct. New services often launch in a subset of Regions first, so availability must be confirmed before committing to a Region.","Where internal staff sit does not matter for this workload; what matters is where the players are."],
 ref:["d1w4","d1c6"], doc:"regions"},

{id:"q01-004", day:1, dom:3, tags:["Regions & AZs","CloudFront"],
 q:"Which statement about AWS edge locations is correct?",
 o:["They are full Regions where customers can launch EC2 instances and RDS databases","They are located inside each Availability Zone to replicate EBS volumes","They serve cached CloudFront content and Route 53 DNS answers close to users","They are reserved for AWS GovCloud workloads that need physical isolation"],
 a:[2],
 x:["Edge locations are not Regions; you cannot launch EC2 instances or RDS databases in them.","EBS volumes are replicated within their own AZ; edge locations are a separate network, not part of AZs.","Correct. Edge locations are far more numerous than Regions, and services such as CloudFront and Route 53 use them to reduce latency for end users.","GovCloud consists of isolated Regions; edge locations are a global network used by all customers."],
 ref:["d1w4","d1c6"], doc:"cloudfront"},

{id:"q01-005", day:1, dom:2, tags:["High availability design","Regions & AZs"],
 q:"An online retailer runs its web application on two EC2 instances in a single Availability Zone. Management wants the application to keep serving customers if that AZ has an outage, without moving to another Region. Which solution meets this requirement?",
 o:["Replace both instances with a larger instance type in the same AZ","Launch both instances in a cluster placement group in the same AZ","Take daily EBS snapshots so the instances can be rebuilt after an outage","Move one instance to a second AZ and put a load balancer in front"],
 a:[3],
 x:["A larger instance type adds capacity, but both instances still fail together with the AZ.","A cluster placement group packs instances close together in one AZ, which does nothing to survive an AZ outage.","Snapshots help recovery, but rebuilding after the outage means downtime; the requirement is to keep serving customers during it.","Correct. AZs are isolated failure domains; spreading instances across two AZs behind an Elastic Load Balancer keeps the application up if one AZ fails."],
 ref:["d1p2","d1w4"], doc:"regions"},

{id:"q01-006", day:1, dom:1, tags:["Regions & AZs"],
 q:"A company stores customer files in an S3 bucket in eu-west-1 and has not configured any replication. Where does AWS store the objects?",
 o:["Only in eu-west-1, unless the company replicates or copies them","In eu-west-1 and also in a paired backup Region that AWS chooses","In every edge location so users anywhere can read them quickly","In a single data center that the company selects in eu-west-1"],
 a:[0],
 x:["Correct. Data stays in the Region you choose; AWS does not move it to another Region unless you configure replication or copy it yourself. This is why Region choice can satisfy data residency rules.","AWS has no automatic paired-Region replication; cross-Region copies happen only when you set up features such as S3 Cross-Region Replication.","Content reaches edge locations only if you put a CloudFront distribution in front of the bucket, and even then only as temporary cached copies.","You do not pick a data center; S3 Standard automatically stores objects redundantly across multiple AZs in the Region."],
 ref:["d1w4","d1c6"], doc:"regions"},

{id:"q01-007", day:1, dom:4, tags:["Regions & AZs"],
 q:"A research team runs a large nightly batch simulation on EC2. There are no data residency rules, results are downloaded the next morning, and every Region under consideration offers the services needed. The team wants to minimize cost. What should drive the Region choice?",
 o:["The Region that is geographically closest to the research team","The Region with the most edge locations nearby to speed up the job","The Region where the team's IAM Identity Center instance is enabled","The Region with the lowest prices for the instance types used"],
 a:[3],
 x:["Proximity matters for interactive latency, but a batch job whose results are collected the next day gains little from it.","Edge locations speed up content delivery to users; they do not make EC2 batch jobs run faster or cheaper.","Identity Center grants access to accounts, and users can then work in any Region, so its home Region does not restrict where workloads run.","Correct. Prices differ between Regions; when compliance, latency and service availability are not deciding factors, price becomes the main criterion."],
 ref:["d1w4","d1c6"], doc:"ec2-pricing"},

{id:"q01-008", day:1, dom:3, tags:["CloudFront"],
 q:"A media company serves images and video clips from an S3 bucket in us-east-1. Users in Europe and Asia report slow load times. The company wants to improve performance for these users with the least operational overhead. Which solution meets these requirements?",
 o:["Replicate the bucket to a Region on each continent and route users by location","Run EC2 instances with larger network bandwidth in front of the bucket","Move the bucket to a Region roughly halfway between Europe and Asia","Create a CloudFront distribution with the S3 bucket as its origin"],
 a:[3],
 x:["Multi-Region replication plus geographic DNS routing could work, but it adds buckets, replication rules and routing to maintain; CloudFront gets the same result with far less effort.","Proxy instances in us-east-1 do not shorten the distance to users and add servers to manage.","A single 'middle' Region still leaves many users far away and does not cache content near them.","Correct. CloudFront caches the objects at edge locations worldwide, so repeat requests are served close to users, with no servers to manage."],
 ref:["d1w4"], doc:"cloudfront"},

{id:"q01-009", day:1, dom:1, tags:["S3 features","CloudFront"],
 q:"A company hosts its marketing site using S3 static website hosting. Security policy now requires that all visitors connect over HTTPS using the company's custom domain. Which solution meets this requirement with the least operational overhead?",
 o:["Enable the HTTPS option in the bucket's static website hosting settings","Put a CloudFront distribution in front of the site with an ACM certificate","Upload the TLS certificate and private key as objects in the bucket","Move the site to an EC2 web server and install a TLS certificate on it"],
 a:[1],
 x:["S3 website endpoints support only HTTP; there is no HTTPS setting for them.","Correct. CloudFront serves the custom domain over HTTPS using a free public certificate from AWS Certificate Manager, and adds edge caching as a bonus.","S3 does not read certificates stored as objects; this would expose the private key and still not enable HTTPS.","This works, but it replaces a serverless site with a server you must patch, scale and maintain."],
 ref:["d1w4","d1p1"], doc:"cloudfront"},

{id:"q01-010", day:1, dom:2, tags:["High availability design","Regions & AZs"],
 q:"An application needs four EC2 instances to handle peak load. It must keep full capacity even if any single Availability Zone fails, and the Region has at least three AZs. Which deployment meets this requirement most cost-effectively?",
 o:["Two instances in each of two AZs, four instances in total","Four instances in each of two AZs, eight instances in total","Two instances in each of three AZs, six instances in total","Six instances in one AZ, leaving spare capacity for growth"],
 a:[2],
 x:["If one AZ fails, only two instances remain, which is half the required capacity.","This keeps full capacity after an AZ failure, but uses eight instances where six would do.","Correct. Losing any one AZ still leaves four instances; spreading across three AZs needs less spare capacity than spreading across two.","All instances share one failure domain, so a single AZ outage takes down the whole application."],
 ref:["d1p2","d1w4","d1c6"], doc:"regions"},

{id:"q01-011", day:1, dom:2, tags:["Regions & AZs","High availability design"],
 q:"Which resources are created in a single Availability Zone? (Choose two.)",
 o:["A VPC subnet","An Amazon VPC","An Amazon Machine Image (AMI)","An Amazon EBS volume","An IAM role"],
 a:[0,3],
 x:["Correct. Each subnet lives entirely in one AZ, so a multi-AZ design needs at least one subnet per AZ.","A VPC is Regional and spans all AZs in its Region; you add subnets to place resources in specific AZs.","An AMI is Regional: it can launch instances in any AZ of its Region and can be copied to other Regions.","Correct. An EBS volume exists in one AZ and can attach only to instances in that same AZ.","IAM is a global service; roles are not tied to any Region or AZ."],
 ref:["d1w4","d1p2","d1c6"], doc:"regions"},

{id:"q01-012", day:1, dom:3, tags:["EC2 instance types"],
 q:"A financial analytics application loads a dataset of several hundred gigabytes into RAM to run risk calculations. On its current general purpose instance, CPU utilization stays low but the process runs out of memory. Which instance family should the company choose?",
 o:["Compute optimized, such as the C family","Storage optimized, such as the I family","Accelerated computing, such as the G family","Memory optimized, such as the R family"],
 a:[3],
 x:["Compute optimized instances have a high ratio of vCPU to memory; the bottleneck here is memory, not CPU.","Storage optimized instances target high local disk I/O, which does not fix running out of RAM.","Accelerated computing instances add GPUs for graphics or ML; that is an expensive way to get more memory.","Correct. Memory optimized instances provide a high ratio of memory to vCPU for large in-memory datasets."],
 ref:["d1w2","d1p3"], doc:"ec2"},

{id:"q01-013", day:1, dom:3, tags:["EC2 instance types"],
 q:"Which EC2 instance family best fits CPU-bound workloads such as dedicated game servers, batch processing and high-performance web servers?",
 o:["General purpose, such as the M family","Memory optimized, such as the X family","Compute optimized, such as the C family","Storage optimized, such as the D family"],
 a:[2],
 x:["General purpose instances balance compute, memory and networking; they work, but a CPU-bound workload gets more performance per dollar from compute optimized.","Memory optimized instances are sized for very large in-memory datasets; that memory would be wasted on CPU-bound work.","Correct. Compute optimized instances have a high vCPU-to-memory ratio and fast processors for compute-intensive tasks.","Storage optimized instances focus on dense local storage and disk throughput, not CPU performance."],
 ref:["d1w2","d1p3"], doc:"ec2"},

{id:"q01-014", day:1, dom:3, tags:["EC2 instance types"],
 q:"A team runs a self-managed NoSQL database cluster that needs very high, low-latency random I/O to locally attached NVMe storage. The database replicates data across nodes itself. Which instance family fits best?",
 o:["Storage optimized, such as the I family","Burstable general purpose, such as the T family","Compute optimized, such as the C family","Accelerated computing, such as the P family"],
 a:[0],
 x:["Correct. Storage optimized instances provide large, fast local NVMe instance store volumes built for very high random IOPS; the database's own replication covers the fact that instance store is not persistent.","Burstable instances suit low, spiky CPU usage and do not offer high-performance local storage.","Compute optimized instances target CPU-heavy work, not local disk I/O.","P instances add GPUs for ML training; GPUs do nothing for a disk-bound database."],
 ref:["d1w2","d1p3"], doc:"ec2"},

{id:"q01-015", day:1, dom:3, tags:["EC2 instance types"],
 q:"A machine learning team needs to train deep learning models that benefit from GPU hardware acceleration. Which EC2 instance family should they use?",
 o:["Memory optimized, such as the R family","Compute optimized, such as the C family","General purpose, such as the M family","Accelerated computing, such as the P family"],
 a:[3],
 x:["Memory optimized instances give lots of RAM per vCPU but have no GPUs.","Compute optimized instances have fast CPUs, but deep learning training runs far faster on GPUs.","General purpose instances balance resources and do not include GPU accelerators.","Correct. Accelerated computing instances (such as P and G, plus Trainium and Inferentia based families) use hardware accelerators for ML and graphics workloads."],
 ref:["d1w2","d1p3"], doc:"ec2"},

{id:"q01-016", day:1, dom:4, tags:["EC2 instance types"],
 q:"An internal wiki runs on one EC2 instance. CPU usage is usually under 10% with short spikes when many employees open pages at once. Which instance choice is most cost-effective?",
 o:["A burstable instance, such as T3 or T4g","A compute optimized instance, such as C7i","A memory optimized instance, such as R7g","An accelerated computing instance, such as G5"],
 a:[0],
 x:["Correct. Burstable instances earn CPU credits while running below their baseline and spend them during spikes, giving a low price for a low baseline with occasional bursts.","Compute optimized instances charge for sustained high CPU capacity that this workload rarely uses.","Memory optimized instances charge for large amounts of RAM that a small wiki does not need.","GPU instances add significant cost and do nothing to serve web pages faster."],
 ref:["d1w2","d1p3"], doc:"ec2"},

{id:"q01-017", day:1, dom:3, tags:["EC2 instance types"],
 q:"An EBS-backed EC2 instance running a reporting application needs more memory. The data on its EBS root volume must be kept, and the team wants the fewest steps. What should the team do?",
 o:["Change the instance type while it runs; EC2 applies the change live","Increase the size of the root EBS volume to give the instance more memory","Stop the instance, change its instance type, and then start it again","Terminate the instance and launch a larger type from the original AMI"],
 a:[2],
 x:["EC2 cannot change the instance type of a running instance; it must be stopped first.","EBS volume size is disk storage, not RAM; memory comes from the instance type.","Correct. For an EBS-backed instance you stop it, modify the instance type, and start it again; the root volume and its data are kept.","A new instance from the original AMI would lack every change made since launch, and the old root volume may be deleted on termination."],
 ref:["d1p3","d1w2"], doc:"ec2"},

{id:"q01-018", day:1, dom:2, tags:["EC2 instance types","EBS & instance store"],
 q:"A team plans to resize an EBS-backed EC2 instance by stopping it, changing the type and starting it again. What should the team expect? (Choose two.)",
 o:["The data on the EBS root volume is erased","The instance receives a new instance ID","Data on any instance store volumes is lost","The primary private IPv4 address changes","The automatically assigned public IPv4 address changes"],
 a:[2,4],
 x:["EBS volumes persist independently of the instance, so the root volume data survives a stop and start.","Stopping and starting keeps the same instance ID; only termination ends an instance.","Correct. Instance store is physically attached to the host; stopping the instance releases that storage and its data.","In a VPC the primary private IPv4 address stays with the instance across stop and start.","Correct. An auto-assigned public IPv4 address is released on stop; use an Elastic IP address if the public address must stay the same."],
 ref:["d1p3","d1w2"], doc:"ec2"},

{id:"q01-019", day:1, dom:4, tags:["EC2 purchase options"],
 q:"A company runs a steady workload 24/7 and will keep it for at least three years. Over that time it expects to switch EC2 instance families and move some services to AWS Fargate. Which purchasing option gives a commitment discount while allowing these changes?",
 o:["Standard Reserved Instances for the current instance type","An EC2 Instance Savings Plan for the current instance family","A Compute Savings Plan with a three-year term","Spot Instances for the entire workload"],
 a:[2],
 x:["Standard RIs are tied to instance attributes and never cover Fargate, so they lose value when the company changes families or moves to containers.","An EC2 Instance Savings Plan is locked to one instance family in one Region and does not apply to Fargate.","Correct. Compute Savings Plans apply automatically across instance families, sizes, Regions and operating systems, and also to Fargate and Lambda, in exchange for a committed hourly spend.","Spot can be interrupted with a two-minute warning, which does not suit a steady production workload, and it is not a commitment discount."],
 ref:["d1w2","d1c7"], doc:"ec2-pricing"},

{id:"q01-020", day:1, dom:4, tags:["EC2 purchase options"],
 q:"Which EC2 purchasing option is the most cost-effective for fault-tolerant, stateless batch jobs that can be stopped and restarted at any time?",
 o:["On-Demand Instances","Dedicated Instances","On-Demand Capacity Reservations","Spot Instances"],
 a:[3],
 x:["On-Demand never interrupts you, but you pay full price for a guarantee these jobs do not need.","Dedicated Instances add a premium for single-tenant hardware, the opposite of saving money.","Capacity Reservations bill at On-Demand rates whether the capacity is used or not, adding cost rather than saving it.","Correct. Spot uses spare EC2 capacity at a steep discount; AWS can reclaim it with a two-minute notice, which interruption-tolerant jobs handle well."],
 ref:["d1w2","d1c7"], doc:"ec2-pricing"},

{id:"q01-021", day:1, dom:4, tags:["EC2 purchase options"],
 q:"A team is testing a new application for six weeks. Usage is unpredictable, and the instances must not be interrupted. Which purchasing option is most cost-effective?",
 o:["A one-year Compute Savings Plan","On-Demand Instances","Spot Instances","Three-year Standard Reserved Instances"],
 a:[1],
 x:["A one-year commitment keeps billing for months after the six-week test ends.","Correct. On-Demand has no commitment and bills only while instances run, which fits short, unpredictable, uninterruptible use.","Spot Instances can be interrupted, which the requirement rules out.","A three-year term is far longer than the six-week need, so almost all of the commitment would be wasted."],
 ref:["d1w2","d1c7"], doc:"ec2-pricing"},

{id:"q01-022", day:1, dom:4, tags:["EC2 purchase options"],
 q:"A company wants to bring its existing server software licenses to AWS. The licenses are counted per physical CPU socket and core, and the vendor requires the company to show which physical server the software runs on. Which EC2 option meets these requirements?",
 o:["Dedicated Hosts","Dedicated Instances","Spot Instances with a launch template","On-Demand Instances with default tenancy"],
 a:[0],
 x:["Correct. A Dedicated Host is a whole physical server for your use, with visibility into sockets and cores and control over instance placement, which supports socket- or core-based bring-your-own-license terms.","Dedicated Instances run on hardware dedicated to your account, but you get no visibility into sockets and cores and no control over which host they use.","Spot Instances run on shared hardware, can be interrupted, and give no control over the physical server.","Default tenancy shares hardware with other customers, so per-socket licensing cannot be tracked."],
 ref:["d1w2","d1c7"], doc:"ec2-pricing"},

{id:"q01-023", day:1, dom:1, tags:["EC2 purchase options"],
 q:"A security team requires that a workload's EC2 instances never share physical hardware with other AWS customers. There are no software licensing constraints and no need to control placement on specific hosts. Which option meets the requirement with the least management effort?",
 o:["Dedicated Hosts","On-Demand Capacity Reservations","A cluster placement group","Dedicated Instances"],
 a:[3],
 x:["Dedicated Hosts also isolate hardware, but you allocate and manage the hosts and their capacity, which is effort the team does not need.","Capacity Reservations guarantee capacity in an AZ; they address availability, not hardware isolation from other customers.","A cluster placement group places instances close together for low latency; it does not prevent sharing hardware with other customers.","Correct. Dedicated Instances run on single-tenant hardware for your account, and AWS handles placement, so there are no hosts to allocate or manage."],
 ref:["d1w2","d1c7"], doc:"ec2"},

{id:"q01-024", day:1, dom:2, tags:["EC2 purchase options"],
 q:"A ticketing company expects a large traffic surge during a two-week concert presale and must be certain it can launch 40 additional instances of a specific type in one Availability Zone. It does not want a one-year or three-year commitment. Which option meets these requirements?",
 o:["Purchase a Compute Savings Plan before the presale","Request Spot Instances when the surge begins","Create an On-Demand Capacity Reservation in that AZ","Buy Regional Reserved Instances for the instance type"],
 a:[2],
 x:["A Savings Plan is a discount for a one- or three-year commitment, and it does not reserve any capacity.","Spot capacity is not guaranteed and can be reclaimed, the opposite of what a presale needs.","Correct. An On-Demand Capacity Reservation reserves capacity for a specific instance type in a specific AZ with no one- or three-year term; you pay On-Demand rates while it is active and cancel it after the event.","Regional Reserved Instances give a billing discount but do not reserve capacity (only zonal RIs do), and every RI requires a one- or three-year term."],
 ref:["d1w2","d1c7"], doc:"ec2-pricing"},

{id:"q01-025", day:1, dom:4, tags:["EC2 purchase options"],
 q:"A web application needs six EC2 instances running at all times for the next three years. During unpredictable promotions it briefly needs up to six more, and those extra instances must not be interrupted. Which combination is most cost-effective? (Choose two.)",
 o:["Cover the six always-on instances with a three-year Savings Plan","Run the always-on instances as Spot Instances","Use On-Demand Instances for the promotional capacity","Use Dedicated Hosts for the promotional capacity","Buy Reserved Instances to cover all twelve instances"],
 a:[0,2],
 x:["Correct. A predictable, always-on baseline is the ideal use of a long-term commitment discount.","Spot can be interrupted at any time, which is risky for capacity that must always be available.","Correct. On-Demand handles short, unpredictable bursts with no commitment and no interruptions.","Dedicated Hosts add cost for single-tenant hardware that nothing in the scenario requires.","Reserving for the peak means paying for six instances that sit idle most of the time."],
 ref:["d1w2","d1c7"], doc:"ec2-pricing"},

{id:"q01-026", day:1, dom:3, tags:["EC2 user data & AMIs"],
 q:"A team wants each new EC2 instance to install a web server and download the latest application build automatically when it first boots. Which EC2 feature should they use?",
 o:["Instance metadata, queried from inside the instance","An IAM instance profile attached at launch","Resource tags applied to the instance","A user data script supplied at launch"],
 a:[3],
 x:["Instance metadata provides information about the instance (ID, IP addresses, role credentials); it does not run setup commands.","An instance profile gives the instance IAM permissions, which the script may need, but it does not run anything.","Tags label resources for organization and billing; they do not execute commands.","Correct. User data passes a shell script or cloud-init directives that run when the instance first boots, which is ideal for bootstrapping software."],
 ref:["d1p3"], doc:"ec2"},

{id:"q01-027", day:1, dom:3, tags:["EC2 user data & AMIs","Auto Scaling"],
 q:"New instances in an Auto Scaling group take about 20 minutes to become ready because the user data script compiles and installs several packages. The company needs instances to serve traffic within a few minutes of launch. What should a solutions architect recommend?",
 o:["Build a custom AMI with the software preinstalled and launch from it","Move the installation commands from user data into instance metadata","Use a larger instance type so the user data script finishes sooner","Increase the Auto Scaling group's health check grace period"],
 a:[0],
 x:["Correct. Baking dependencies into a 'golden' AMI removes the slow install from boot time; user data can still apply small, instance-specific settings.","Instance metadata is read-only information about the instance; it cannot run installation commands.","A larger instance may shave some time off compiling, but it costs more and still repeats the full install on every launch.","A longer grace period only delays health checks; it does not make instances ready any sooner."],
 ref:["d1p3","d1w2"], doc:"ec2"},

{id:"q01-028", day:1, dom:2, tags:["EC2 user data & AMIs","Regions & AZs"],
 q:"A company has a custom AMI in eu-west-1 and wants to launch the same server configuration in ap-southeast-2 for a new customer base. What must the company do?",
 o:["Nothing; AMIs are global and appear in every Region automatically","Copy the AMI to ap-southeast-2 and launch from the copy","Attach the AMI's EBS snapshot directly to instances in the new Region","Reference the eu-west-1 AMI ID in a launch template in the new Region"],
 a:[1],
 x:["AMIs are Regional resources; an AMI in eu-west-1 is not available in other Regions until you copy it.","Correct. Copying the AMI to the target Region creates a new AMI there, with its own ID, that launches identical instances.","EBS snapshots are also Regional and are not attached to instances directly; they would have to be copied to the other Region first.","A launch template can only use AMIs that exist in its own Region, so the eu-west-1 AMI ID is not valid there."],
 ref:["d1p3","d1w4"], doc:"ec2"},

{id:"q01-029", day:1, dom:1, tags:["EC2 user data & AMIs"],
 q:"Why should a database password not be placed in an EC2 instance's user data?",
 o:["User data is limited to plain-text shell scripts and cannot hold passwords","User data is deleted after first boot, so the password would be lost","User data is not encrypted and can be read through the instance metadata","User data is visible only to the root user, so the application cannot read it"],
 a:[2],
 x:["User data can contain any text, which is exactly how a secret ends up there; the problem is exposure, not format.","User data is not deleted after boot; it remains retrievable for the life of the instance.","Correct. Any process on the instance, and anyone allowed to view the instance's attributes, can read user data. Secrets belong in a secrets store that the instance reads using an IAM role.","Any process on the instance that can reach the instance metadata service can read user data, so it is not limited to root."],
 ref:["d1p3"], doc:"ec2"},

{id:"q01-030", day:1, dom:3, tags:["Lambda"],
 q:"A photo-sharing startup must create a thumbnail each time a user uploads an image to an S3 bucket. Each conversion takes a few seconds, upload volume is unpredictable, and the team wants the least operational overhead. Which compute option should it use?",
 o:["An AWS Lambda function triggered by S3 event notifications","An Auto Scaling group of EC2 instances that polls the bucket","An Elastic Beanstalk environment running a worker application","An Amazon EKS cluster with a deployment that watches the bucket"],
 a:[0],
 x:["Correct. Lambda runs short, event-driven code with no servers to manage, scales with the number of uploads, and charges only for the time the code runs.","This works, but the team must manage instances, scaling and polling logic, and pays for idle capacity.","Beanstalk simplifies deployment but still runs EC2 instances continuously, adding cost and overhead for short bursts of work.","Running Kubernetes for a simple event-driven task adds significant operational complexity."],
 ref:["d1w3","d1c8"], doc:"lambda"},

{id:"q01-031", day:1, dom:3, tags:["Containers","Lambda"],
 q:"A data team has packaged a nightly processing job as a container image. The job runs for about two hours, and the team does not want to provision or manage servers. Which solution meets these requirements?",
 o:["Run the job as an AWS Lambda function on a nightly schedule","Run the job on an EC2 instance with a cron entry","Run the job as an Amazon ECS task on AWS Fargate on a schedule","Deploy the job to an Elastic Beanstalk web server environment"],
 a:[2],
 x:["A Lambda function invocation times out after at most 15 minutes (90 minutes for asynchronous invocations on Lambda Managed Instances), so a two-hour job cannot finish.","This works, but the team would have to patch and manage the instance, which they want to avoid.","Correct. Fargate runs containers without servers to manage and puts no time limit on a task; an ECS scheduled task can start the job each night.","A web server environment is meant for continuously running web apps and still provisions EC2 instances behind the scenes."],
 ref:["d1w3","d1c8"], doc:"fargate"},

{id:"q01-032", day:1, dom:3, tags:["Containers"],
 q:"A company runs its microservices on a self-managed Kubernetes cluster on premises and uses Kubernetes manifests and tooling throughout. It wants to move to AWS with minimal changes and without managing worker nodes. Which solution meets these requirements?",
 o:["Amazon ECS with the EC2 launch type","AWS Elastic Beanstalk with the Docker platform","Amazon EKS with AWS Fargate","AWS Lambda with container image support"],
 a:[2],
 x:["ECS uses its own task definitions rather than Kubernetes manifests, and the EC2 launch type means managing instances.","Beanstalk can run Docker containers, but it deploys them from its own application and environment configuration, not from the team's Kubernetes manifests and tooling.","Correct. EKS runs upstream Kubernetes, so existing manifests and tools keep working, and Fargate removes the need to manage worker nodes.","Lambda can run container images, but the microservices would need refactoring into functions and the Kubernetes tooling would no longer apply."],
 ref:["d1w3","d1c8"], doc:"eks"},

{id:"q01-033", day:1, dom:3, tags:["Elastic Beanstalk"],
 q:"A small development team has a Python web application. They want to upload their code and have AWS provision and manage the load balancer, scaling and health monitoring, while still being able to access the underlying EC2 instances if needed. Which service best meets these requirements?",
 o:["AWS Elastic Beanstalk","Amazon ECS on AWS Fargate","AWS Lambda","Amazon EC2 with a launch template"],
 a:[0],
 x:["Correct. Elastic Beanstalk takes application code and handles capacity provisioning, load balancing, auto scaling and health monitoring, while you keep full access to the resources it creates.","Fargate would require containerizing the app and defining tasks and services, and there are no EC2 instances to access.","Lambda would require restructuring the web app into functions, and there are no underlying instances to access.","Plain EC2 leaves the team to build and run the load balancer, scaling and monitoring themselves."],
 ref:["d1w3","d1c8"], doc:"beanstalk"},

{id:"q01-034", day:1, dom:3, tags:["EC2 instance types","Containers"],
 q:"A manufacturer is migrating a legacy application that requires a specific Linux kernel module and a licensed monitoring agent installed at the operating system level. The application runs continuously. Which compute service meets these requirements?",
 o:["AWS Lambda","Amazon ECS on AWS Fargate","Amazon EC2","Amazon EKS on AWS Fargate"],
 a:[2],
 x:["A Lambda function runs in an execution environment that AWS manages, with no way to load kernel modules or install host-level agents, and its invocations are time-limited, which rules out an application that runs continuously.","Fargate manages the underlying host for you, so you cannot load custom kernel modules or install host-level agents.","Correct. EC2 gives full control of the operating system, including kernel modules and OS-level agents.","EKS on Fargate has the same restriction as ECS on Fargate: no access to the underlying host or its kernel."],
 ref:["d1w3","d1c8","d1w2"], doc:"ec2"},

{id:"q01-035", day:1, dom:3, tags:["Lambda"],
 q:"A team plans to run AWS Lambda functions with the default on-demand configuration. Which statements about this setup are correct? (Choose two.)",
 o:["You choose and patch the operating system for each function","A single invocation can run for at most 15 minutes","Each function needs an EC2 instance that you keep running","Functions must be deployed to a container cluster you manage","You pay for requests and execution time, not idle capacity"],
 a:[1,4],
 x:["AWS manages the operating system and managed runtimes; you supply only code and configuration.","Correct. In this configuration the maximum function timeout is 15 minutes, so longer single runs fit containers or EC2 better. (Lambda Managed Instances, an opt-in model, allow up to 90 minutes for asynchronous invocations.)","In the default model there are no instances for you to provision or keep running; AWS runs the functions on capacity it manages.","Lambda handles all infrastructure; you upload a .zip package or container image and AWS runs it.","Correct. On-demand Lambda bills per request and per unit of execution duration, so idle time costs nothing for compute; provisioned concurrency and Lambda Managed Instances are opt-in models that also bill for capacity."],
 ref:["d1w3","d1c8"], doc:"lambda"},

{id:"q01-036", day:1, dom:3, tags:["Containers"],
 q:"Which statement correctly describes what AWS Fargate provides for container workloads?",
 o:["A managed registry for storing and versioning container images","A platform that deploys application code onto EC2 instances it creates","A managed Kubernetes control plane that you pair with your own nodes","A serverless compute engine that runs containers for ECS and EKS"],
 a:[3],
 x:["That is Amazon ECR (Elastic Container Registry), which Fargate tasks often pull their images from.","That describes Elastic Beanstalk, which creates and manages EC2 instances for your code.","That describes Amazon EKS; Fargate is one way to run EKS pods without managing nodes.","Correct. Fargate runs containers without you provisioning, patching or scaling servers, and it works with both ECS and EKS."],
 ref:["d1w3","d1c8"], doc:"fargate"},

{id:"q01-037", day:1, dom:4, tags:["S3 features"],
 q:"A nonprofit needs to publish a small website made of HTML, CSS, JavaScript and images, with no server-side code. The organization wants the lowest cost and no servers to manage. Which solution meets these requirements?",
 o:["Host the site on an EC2 instance running Apache","Deploy the site to an Elastic Beanstalk environment","Enable static website hosting on an S3 bucket","Run the site in a container on Amazon ECS with Fargate"],
 a:[2],
 x:["An EC2 web server works, but it must be patched and paid for around the clock.","Beanstalk still runs EC2 instances (and often a load balancer) behind the scenes, which costs more than needed.","Correct. S3 serves static files directly, scales automatically, and charges only for storage, requests and data transfer.","A container service adds running tasks to pay for and configure when the content is just static files."],
 ref:["d1p1"], doc:"s3"},

{id:"q01-038", day:1, dom:1, tags:["S3 features","S3 security"],
 q:"A developer wants anyone on the internet to view a static site through an S3 bucket's website endpoint. Which configurations are required? (Choose two.)",
 o:["Enable static website hosting and set an index document","Turn on S3 Versioning for the bucket","Attach an IAM role to the bucket so visitors can assume it","Disable Block Public Access and add a public-read bucket policy","Enable S3 Transfer Acceleration on the bucket"],
 a:[0,3],
 x:["Correct. Website hosting must be turned on and an index document (such as index.html) defined for the website endpoint to serve pages.","Versioning protects against overwrites and deletions but is not needed to serve a website.","Buckets do not have roles, and anonymous visitors cannot assume IAM roles to browse a website.","Correct. The website endpoint serves only publicly readable objects, so Block Public Access must allow it and a bucket policy must grant <code>s3:GetObject</code> to everyone.","Transfer Acceleration speeds up long-distance transfers through a separate accelerate endpoint; it is not needed to serve a website."],
 ref:["d1p1"], doc:"s3"},

{id:"q01-039", day:1, dom:3, tags:["S3 features","Lambda"],
 q:"A company hosts a static website on Amazon S3. It now needs a contact form that saves submissions to a database, and the company wants to keep the site serverless. Which approach should a solutions architect recommend?",
 o:["Enable server-side scripting such as PHP in the bucket's website settings","Have the page call an Amazon API Gateway API that invokes a Lambda function","Move the entire website to an EC2 instance that runs a PHP interpreter","Add an S3 lifecycle rule that loads new form objects into the database"],
 a:[1],
 x:["S3 static website hosting serves files only; it cannot execute server-side code such as PHP.","Correct. Client-side JavaScript posts the form to API Gateway, which invokes a Lambda function that writes to the database, so no servers are needed.","An EC2 web server can run PHP, but the site would no longer be serverless and the server must be managed and patched.","Lifecycle rules only transition or expire objects; they cannot run code or write to a database."],
 ref:["d1w3","d1p1"], doc:"lambda"},

{id:"q01-040", day:1, dom:1, tags:["Root user & MFA"],
 q:"Which practices follow AWS recommendations for protecting an account's root user? (Choose two.)",
 o:["Use the root user for daily administration tasks","Share the root password with every administrator","Enable multi-factor authentication on the root user","Do not create root access keys, and delete any that exist","Rotate root access keys every 90 days for CLI use"],
 a:[2,3],
 x:["Daily work should use a less-privileged identity such as an IAM Identity Center user; the root user is kept for the few tasks that require it.","Sharing the root password removes accountability and widens exposure; administrators should each have their own identity.","Correct. MFA protects the most privileged identity in the account even if its password leaks.","Correct. Root access keys give unrestricted programmatic access to the account; AWS recommends having none at all.","Rotation still leaves long-term root keys on disk; the recommendation is to have no root access keys."],
 ref:["d1b1","d1c5"], doc:"iam"},

{id:"q01-041", day:1, dom:1, tags:["Root user & MFA"],
 q:"In a standalone AWS account that is not part of AWS Organizations, which task requires signing in as the root user?",
 o:["Closing the AWS account","Creating a new IAM Identity Center permission set","Launching EC2 instances in a different Region","Creating a zero-spend budget in AWS Budgets"],
 a:[0],
 x:["Correct. Closing a standalone account is one of the few tasks that require root user credentials, which is why root is kept only for tasks like this.","Permission sets can be created by any identity with the right IAM Identity Center permissions, such as an administrator signed in through the access portal.","Any identity with EC2 permissions can launch instances in any enabled Region.","Budgets can be created by IAM principals that have AWS Budgets permissions; root is not required."],
 ref:["d1b1","d1c5"], doc:"iam"},

{id:"q01-042", day:1, dom:1, tags:["IAM Identity Center & federation"],
 q:"A company has 40 engineers who need access to six AWS accounts. Employees already sign in with the corporate identity provider, and security requires central access management with short-lived credentials instead of long-term keys. Which solution meets these requirements?",
 o:["Use IAM Identity Center with the IdP and assign permission sets","Create IAM users with access keys for each engineer in every account","Create one shared IAM user per team and rotate its password monthly","Create an Amazon Cognito user pool and add the engineers to it"],
 a:[0],
 x:["Correct. IAM Identity Center federates with the existing identity provider, assigns permission sets per account from one place, and issues temporary credentials through the access portal and CLI.","This creates 240 sets of long-term credentials to manage, the opposite of central control and short-lived access.","Shared users remove individual accountability and still rely on long-term credentials.","Cognito user pools handle customer sign-in for your own applications, not workforce access to AWS accounts."],
 ref:["d1c1","d1c4"], doc:"identity-center"},

{id:"q01-043", day:1, dom:1, tags:["IAM Identity Center & federation"],
 q:"In IAM Identity Center, what is a permission set?",
 o:["A group of users who share the same job function in the directory","A policy attached to the organization that limits what any account can do","A template of policies provisioned as an IAM role in assigned accounts","A password and MFA policy that applies to all users of the access portal"],
 a:[2],
 x:["That describes a group; groups are assigned permission sets but are not permission sets themselves.","That describes a service control policy (SCP) in AWS Organizations, which sets maximum permissions for accounts.","Correct. A permission set defines what users can do; when you assign it to a user or group for an account, Identity Center creates a matching IAM role in that account.","Authentication settings such as MFA are configured separately; permission sets define authorization."],
 ref:["d1c3","d1c4","d1c1"], doc:"identity-center"},

{id:"q01-044", day:1, dom:1, tags:["IAM Identity Center & federation","Root user & MFA"],
 q:"A developer has just created a new AWS account and secured the root user with MFA. She needs everyday administrator access to the console and the AWS CLI using short-lived credentials. Which approach follows AWS best practices?",
 o:["Create root user access keys and store them in the CLI configuration","Create an IAM user with long-term access keys and full administrator rights","Keep using the root user with MFA for both console and CLI work","Enable IAM Identity Center and give her an administrator permission set"],
 a:[3],
 x:["Root access keys grant unrestricted, long-term access; AWS recommends never creating them.","An IAM user works, but its access keys are long-term credentials, which fails the short-lived requirement.","The root user should be reserved for the few tasks that require it, not everyday work.","Correct. Identity Center users sign in through the access portal and get temporary credentials for the console, and for the CLI via <code>aws configure sso</code>."],
 ref:["d1c1","d1c5","d1c3"], doc:"identity-center"},

{id:"q01-045", day:1, dom:4, tags:["Cost management tools"],
 q:"A student opening a new AWS account wants to be emailed when the account starts incurring any charges at all, with the least setup effort. What should the student configure?",
 o:["A monthly spending report in AWS Cost Explorer","An estimate in the AWS Pricing Calculator","A zero-spend budget in AWS Budgets","A Cost and Usage Report export to Amazon S3"],
 a:[2],
 x:["Cost Explorer visualizes and forecasts spend, but you have to look at it yourself; it does not alert on a threshold.","The Pricing Calculator estimates costs before you deploy; it does not monitor actual spend.","Correct. The zero-spend budget template emails you once actual spend rises above zero, beyond Free Tier usage. AWS Budgets updates its data up to three times a day, so the alert can arrive hours after the first charge, not instantly.","Cost and Usage Reports deliver detailed billing data files for analysis; they do not send alerts."],
 ref:["d1d1","d1d2"], doc:"budgets"},

{id:"q01-046", day:1, dom:4, tags:["Cost management tools"],
 q:"A finance team wants to be notified by email and in a chat channel when an account's actual spend reaches 80% of a $5,000 monthly limit, and also when spend is forecast to exceed the full amount. Which solution meets these requirements with the least effort?",
 o:["Create an AWS Budgets budget with actual and forecast alerts to SNS","Review AWS Cost Explorer every morning and post a summary to the channel","Enable AWS Cost Anomaly Detection with a monitor for the account","Run a Lambda function every hour that checks spend and posts the results"],
 a:[0],
 x:["Correct. AWS Budgets supports alert thresholds on both actual and forecasted cost and can notify email addresses and an SNS topic that forwards to chat tools.","Manual review is slow, error-prone and is not a notification system.","Cost Anomaly Detection uses machine learning to flag unusual spending patterns; it does not track progress toward a fixed monthly budget.","Custom polling code is more effort to build and maintain than a built-in budget alert."],
 ref:["d1d1"], doc:"budgets"},

{id:"q01-047", day:1, dom:4, tags:["Cost management tools"],
 q:"A startup gives its developers a sandbox account. When monthly spend passes the sandbox budget, it wants to automatically prevent developers from launching new resources, without writing custom code. Which solution meets this requirement?",
 o:["A zero-spend budget that emails each developer when costs begin","A budget action that applies a deny IAM policy at the threshold","A Cost Explorer forecast reviewed daily by the team lead","A Pricing Calculator estimate attached to each deployment"],
 a:[1],
 x:["A zero-spend budget only sends notifications; it does not stop anyone from launching resources.","Correct. AWS Budgets actions can automatically apply an IAM policy or SCP, or stop selected EC2 and RDS instances, when a threshold is crossed.","Cost Explorer is an analysis tool; a manual review cannot automatically block launches.","The Pricing Calculator estimates costs ahead of time; it has no enforcement capability."],
 ref:["d1d1"], doc:"budgets"},

{id:"q01-048", day:1, dom:1, tags:["Shared responsibility"],
 q:"Under the AWS shared responsibility model, which task is the customer's responsibility when running applications on Amazon EC2?",
 o:["Patching the guest operating system on the instances","Maintaining the hypervisor that isolates instances","Securing the physical data center facilities","Replacing failed disks in the underlying host servers"],
 a:[0],
 x:["Correct. EC2 is infrastructure as a service, so the customer manages the guest OS (updates and security patches), the applications and the security group rules.","The virtualization layer is part of the infrastructure that AWS secures (security of the cloud).","Physical security of the facilities is always AWS's responsibility.","Host hardware maintenance belongs to AWS; customers never touch the physical servers."],
 ref:["d1w1","d1w2"], doc:"shared"},

{id:"q01-049", day:1, dom:1, tags:["Shared responsibility","Lambda"],
 q:"A company is moving an application from EC2 instances to AWS Lambda functions. Which responsibilities stay with the company after the move? (Choose two.)",
 o:["Patching the operating system of the servers that run the functions","Securing the function code and its third-party libraries","Scaling the fleet of hosts as request volume changes","Granting the function's execution role only the permissions it needs","Maintaining the physical network between Availability Zones"],
 a:[1,3],
 x:["With Lambda, AWS manages and patches the underlying operating system and the managed runtimes.","Correct. The customer always owns the security of its own code and the dependencies it packages.","Lambda scales automatically; AWS manages the underlying capacity.","Correct. Identity and access management, including least-privilege execution roles, remains the customer's job.","The physical network is part of the infrastructure that AWS secures and operates."],
 ref:["d1w1","d1w3"], doc:"shared"},

{id:"q01-050", day:1, dom:1, tags:["Shared responsibility","S3 security"],
 q:"A healthcare startup accidentally made an S3 bucket containing patient documents public by editing its bucket policy. An auditor asks who was responsible for preventing this exposure under the shared responsibility model. What is the correct answer?",
 o:["AWS, because S3 is a managed service and AWS secures the data stored in it","The startup, because configuring access to its data is security in the cloud","AWS, because it should reject any bucket policy that grants public access","Both equally, because S3 is a shared service with joint data ownership"],
 a:[1],
 x:["AWS secures the infrastructure that runs S3, but the customer controls who can access its data.","Correct. Customers are responsible for their data and its access configuration, such as bucket policies, IAM and Block Public Access settings (security in the cloud).","S3 Block Public Access is on by default for new buckets, but it is a customer-controlled setting; AWS does not override the access choices a customer makes.","Responsibility is divided by layer, not shared equally; data and access configuration belong to the customer."],
 ref:["d1w1","d1p1"], doc:"shared"}
);
